<template>
  <div class="app-page" v-loading="loading">
    <div class="app-page-head"><div class="title-line"><el-button text aria-label="返回执行记录" @click="$router.push('/runs')"><el-icon><ArrowLeft /></el-icon></el-button><div><h1>{{ run?.name || '运行详情' }}</h1><p><code>{{ run?.id || runId }}</code></p></div></div><div><el-button v-if="canCancel" type="danger" plain @click="cancel">取消运行</el-button><el-button type="primary" @click="openReport">查看报告</el-button></div></div>
    <el-alert v-if="run?.error_message" :title="run.error_message" type="error" show-icon :closable="false" />
    <div class="metric-grid"><el-card v-for="item in metrics" :key="item.label" shadow="never"><span>{{ item.label }}</span><strong>{{ item.value }}</strong></el-card></div>
    <div class="detail-grid">
      <el-card shadow="never"><template #header><b>执行时间线</b></template><el-timeline v-if="events.length"><el-timeline-item v-for="event in events" :key="event.sequence" :timestamp="formatTime(event.created_at)" :type="eventType(event.event_type)"><b>{{ eventLabel(event.event_type) }}</b><p v-if="event.payload?.error">{{ event.payload.error }}</p></el-timeline-item></el-timeline><el-empty v-else description="暂无事件证据" /></el-card>
      <el-card shadow="never"><template #header><b>运行上下文</b></template><el-descriptions :column="1" border><el-descriptions-item label="状态"><el-tag :type="statusType(run?.status)">{{ statusLabel(run?.status) }}</el-tag></el-descriptions-item><el-descriptions-item label="触发方式">{{ run?.trigger_type || 'manual' }}</el-descriptions-item><el-descriptions-item label="代码版本">{{ run?.source_ref || '—' }}</el-descriptions-item><el-descriptions-item label="创建时间">{{ formatTime(run?.created_at) }}</el-descriptions-item><el-descriptions-item label="完成时间">{{ formatTime(run?.completed_at) }}</el-descriptions-item></el-descriptions></el-card>
    </div>
  </div>
</template>
<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ArrowLeft } from '@element-plus/icons-vue';import { ElMessage,ElMessageBox } from 'element-plus';import { testRunApi } from '@/api'
const route=useRoute(),router=useRouter(),runId=String(route.params.id);const loading=ref(false),run=ref<any>(null),events=ref<any[]>([]),summary=ref<any>({});const labels:any={pending:'等待中',executing:'执行中',completed:'已完成',failed:'失败',cancelled:'已取消'}
const canCancel=computed(()=>['pending','executing','pulling','analyzing','generating','reporting'].includes(run.value?.status));const metrics=computed(()=>[{label:'执行进度',value:`${run.value?.progress||0}%`},{label:'用例总数',value:summary.value.total??'—'},{label:'通过',value:summary.value.passed??'—'},{label:'失败',value:summary.value.failed??'—'}])
function statusLabel(v:string){return labels[v]||v||'未知'}function statusType(v:string){return v==='completed'?'success':v==='failed'?'danger':v==='cancelled'?'info':'warning'}function formatTime(v:string){return v?new Date(v).toLocaleString('zh-CN'):'—'}function eventType(v:string){return v?.includes('failed')?'danger':v?.includes('completed')?'success':'primary'}function eventLabel(v:string){return ({'run.created':'运行已创建','run.started':'开始执行','run.completed':'执行完成','run.failed':'执行失败','case.started':'开始用例','case.completed':'用例完成'} as any)[v]||v}
async function load(){loading.value=true;try{const [a,b,c]:any=await Promise.all([testRunApi.get(runId),testRunApi.getEvents(runId),testRunApi.getExecSummary(runId)]);run.value=a?.data;events.value=b?.data?.list||b?.data||[];summary.value=c?.data||{}}finally{loading.value=false}}
async function cancel(){await ElMessageBox.confirm('确定取消本次运行？','取消运行',{type:'warning'});await testRunApi.cancel(runId);ElMessage.success('已提交取消请求');load()}function openReport(){router.push(`/report/${runId}`)}onMounted(load)
</script>
<style scoped>.app-page-head,.title-line{display:flex;align-items:flex-start;justify-content:space-between}.title-line{justify-content:flex-start;gap:8px}.app-page-head h1{margin:0 0 5px;font-size:22px}.app-page-head p{margin:0;color:var(--app-text-placeholder)}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.metric-grid span{display:block;color:var(--app-text-secondary);font-size:13px}.metric-grid strong{display:block;font-size:25px;margin-top:8px}.detail-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(300px,1fr);gap:14px}.el-alert{margin-top:14px}.el-timeline p{color:var(--app-danger);margin:4px 0}@media(max-width:900px){.metric-grid{grid-template-columns:repeat(2,1fr)}.detail-grid{grid-template-columns:1fr}}</style>
